import React, { useEffect, useState } from "react";
import { getUsers, deleteUser } from "./api"; // Import API functions

const UserManagement = () => {
    const [users, setUsers] = useState([]); // State for user list
    const [loading, setLoading] = useState(true); // State for loading status
    const [error, setError] = useState(null); // State for error handling

    // Fetch users from the API
    useEffect(() => {
        const fetchUsers = async () => {
            try {
                setLoading(true); // Start the loader
                const data = await getUsers(); // Fetch users
                setUsers(data); // Update the state with fetched users
            } catch (error) {
                setError(error.message); // Capture any errors
            } finally {
                setLoading(false); // Stop the loader
            }
        };

        fetchUsers(); // Trigger the fetch
    }, []);

    // Handle user deletion
    const handleDeleteUser = async (userId) => {
        try {
            await deleteUser(userId); // Call API to delete user
            setUsers(users.filter((user) => user.id !== userId)); // Update state to remove deleted user
        } catch (error) {
            alert("Failed to delete user: " + error.message); // Show error message
        }
    };

    // Render loading state
    if (loading) {
        return <div>Loading...</div>;
    }

    // Render error state
    if (error) {
        return <div>Error: {error}</div>;
    }

    // Render user list
    return (
        <div>
            <h1>User Management</h1>
            {users.length === 0 ? (
                <p>No users found.</p> // Message when there are no users
            ) : (
                <ul>
                    {users.map((user) => (
                        <li key={user.id}>
                            {user.name} ({user.email}){" "}
                            <button onClick={() => handleDeleteUser(user.id)}>
                                Delete
                            </button>
                        </li>
                    ))}
                </ul>
            )}
        </div>
    );
};

export default UserManagement;
